<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { Connection, Delete, Edit, Key, Plus } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { workbenchApi, workbenchMessage } from '../api'
import type { Provider, ProviderInput } from '../types'

const loading = ref(true); const saving = ref(false); const dialog = ref(false); const editing = ref(''); const providers = ref<Provider[]>([])
const form = reactive<ProviderInput>({ name: '', baseUrl: 'https://api.openai.com/v1', defaultModel: '', apiKey: '', enabled: true })
async function load() { loading.value = true; try { providers.value = await workbenchApi.providers() } catch (error) { ElMessage.error(workbenchMessage(error, '模型连接加载失败')) } finally { loading.value = false } }
function create() { editing.value = ''; Object.assign(form, { name: '', baseUrl: 'https://api.openai.com/v1', defaultModel: '', apiKey: '', enabled: true }); dialog.value = true }
function edit(item: Provider) { editing.value = item.id; Object.assign(form, { name: item.name, baseUrl: item.baseUrl, defaultModel: item.defaultModel, apiKey: '', enabled: item.enabled }); dialog.value = true }
async function save() { if (!form.name.trim() || !form.baseUrl.trim() || !form.defaultModel.trim()) { ElMessage.warning('请填写完整信息'); return }; saving.value = true; try { editing.value ? await workbenchApi.updateProvider(editing.value, { ...form }) : await workbenchApi.createProvider({ ...form }); dialog.value = false; ElMessage.success('模型连接已保存'); await load() } catch (error) { ElMessage.error(workbenchMessage(error, '保存失败')) } finally { saving.value = false } }
async function test(item: Provider) { try { const result = await workbenchApi.testProvider(item.id); ElMessage.success(`连接正常，延迟 ${result.latencyMs} ms`) } catch (error) { ElMessage.error(workbenchMessage(error, '连接测试失败')) } }
async function remove(item: Provider) { try { await ElMessageBox.confirm(`确定删除“${item.name}”吗？`, '删除模型连接', { type: 'warning' }); await workbenchApi.deleteProvider(item.id); await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(workbenchMessage(error, '删除失败')) } }
onMounted(load)
</script>

<template><div class="page-stack ai-page"><header class="page-heading"><div><h2>模型连接</h2><p>API Key 由 AI Workbench 后端加密保存</p></div><el-button type="primary" :icon="Plus" @click="create">添加连接</el-button></header><section v-loading="loading" class="ai-provider-grid"><article v-for="item in providers" :key="item.id"><header><span><el-icon><Connection /></el-icon></span><el-tag :type="item.enabled ? 'success' : 'info'" effect="plain">{{ item.enabled ? '已启用' : '已停用' }}</el-tag></header><h3>{{ item.name }}</h3><p>{{ item.baseUrl }}</p><dl><div><dt>默认模型</dt><dd>{{ item.defaultModel }}</dd></div><div><dt>访问密钥</dt><dd><el-icon><Key /></el-icon>{{ item.hasApiKey ? '已加密配置' : '无需密钥' }}</dd></div></dl><footer><el-button @click="test(item)">测试连接</el-button><span><el-button text :icon="Edit" aria-label="编辑" @click="edit(item)" /><el-button text type="danger" :icon="Delete" aria-label="删除" @click="remove(item)" /></span></footer></article></section><el-empty v-if="!loading && !providers.length" description="还没有模型连接"><el-button type="primary" @click="create">添加连接</el-button></el-empty><el-dialog v-model="dialog" :title="editing ? '编辑模型连接' : '添加模型连接'" width="min(520px, 94vw)"><el-form label-position="top"><el-form-item label="连接名称"><el-input v-model="form.name" maxlength="100" /></el-form-item><el-form-item label="API Base URL"><el-input v-model="form.baseUrl" /></el-form-item><el-form-item label="默认模型"><el-input v-model="form.defaultModel" /></el-form-item><el-form-item label="API Key"><el-input v-model="form.apiKey" type="password" show-password :placeholder="editing ? '留空保留原密钥' : '本地模型可留空'" autocomplete="new-password" /></el-form-item><el-form-item label="状态"><el-switch v-model="form.enabled" active-text="启用" inactive-text="停用" /></el-form-item></el-form><template #footer><el-button @click="dialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog></div></template>

<style scoped>
.ai-provider-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:14px }.ai-provider-grid article{padding:18px;background:var(--surface);border:1px solid var(--line);border-radius:6px}.ai-provider-grid header,.ai-provider-grid footer,.ai-provider-grid dl div{display:flex;align-items:center;justify-content:space-between;gap:10px}.ai-provider-grid header>span{display:grid;place-items:center;width:38px;height:38px;color:var(--theme-primary-dark);background:var(--theme-primary-light-9);border-radius:6px}.ai-provider-grid h3{margin-top:16px;font-size:15px}.ai-provider-grid>article>p{overflow:hidden;margin-top:6px;color:var(--muted);font-size:11px;text-overflow:ellipsis;white-space:nowrap}.ai-provider-grid dl{margin:16px 0;padding:10px 0;border-block:1px solid var(--line)}.ai-provider-grid dl div{margin:7px 0;font-size:12px}.ai-provider-grid dt{color:var(--muted)}.ai-provider-grid dd{display:flex;align-items:center;gap:4px;overflow:hidden;margin:0;text-overflow:ellipsis;white-space:nowrap}@media(max-width:1000px){.ai-provider-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.ai-provider-grid{grid-template-columns:1fr}}
</style>
